pub fn alpha(value: u8) -> u8 {
    let first = value * 2;
    let second = first + 1;
    let third = second * 3;
    let fourth = third + 4;
    let fifth = fourth * 5;
    fifth
}

pub fn beta(value: u8) -> u8 {
    let first = value * 3;
    let second = first + 2;
    let third = second * 4;
    let fourth = third + 5;
    let fifth = fourth * 6;
    fifth
}
